import json
import pandas as pd
import pyarrow as pa
import pyarrow.parquet as pq
from datetime import datetime, date

FIELDS = ["name", "email", "created_date"]  # unified order for conflict scanning

# --- per-source field mapping ---
MAPS = {
    "source_a": {
        "user_id": ["user_id", "id", "userId"],
        "name": ["name", "full_name", "userName", "user_name", "fullname"],
        "email": ["email", "email_address", "emailAddress"],
        "created_date": ["created_date", "registration_date", "created_at", "joined", "createdAt"],
        "status": ["status"],
    },
    "source_b": {
        "user_id": ["user_id", "id", "userId"],
        "name": ["name", "full_name", "userName", "user_name", "fullname"],
        "email": ["email", "email_address", "emailAddress"],
        "created_date": ["created_date", "registration_date", "created_at", "joined", "createdAt"],
        "status": ["status", "is_active", "active"],
    },
    "source_c": {
        "user_id": ["user_id", "id", "userId"],
        "name": ["name", "full_name", "userName", "user_name", "fullname"],
        "email": ["email", "email_address", "emailAddress"],
        "created_date": ["created_date", "registration_date", "created_at", "joined", "createdAt"],
        "status": ["status", "is_active", "active"],
    },
}


def load(path, kind):
    if kind == "json":
        with open(path) as f:
            data = json.load(f)
        if isinstance(data, dict):
            for k in ("users", "data", "records", "rows", "items"):
                if k in data and isinstance(data[k], list):
                    data = data[k]
                    break
        return pd.DataFrame(data)
    if kind == "csv":
        return pd.read_csv(path)
    return pd.read_parquet(path)


def normalize_date(v):
    if v is None:
        return None
    if isinstance(v, (pd.Timestamp, datetime)):
        return v.strftime("%Y-%m-%d")
    if isinstance(v, date):
        return v.strftime("%Y-%m-%d")
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        try:
            return pd.to_datetime(v, unit="ms" if v > 1e11 else "s").strftime("%Y-%m-%d")
        except Exception:
            return str(v)
    s = str(v).strip()
    if not s or s.lower() in ("nan", "none", "nat", "null"):
        return None
    try:
        return pd.to_datetime(s, errors="raise").strftime("%Y-%m-%d")
    except Exception:
        return s


def clean(v):
    if v is None:
        return None
    if isinstance(v, float) and pd.isna(v):
        return None
    if v is pd.NaT:
        return None
    if isinstance(v, str):
        s = v.strip()
        if not s or s.lower() in ("nan", "none", "nat", "null"):
            return None
        return s
    return v


def norm_status(v):
    v = clean(v)
    if v is None:
        return None
    if isinstance(v, bool):
        return "active" if v else "inactive"
    s = str(v).strip().lower()
    if s in ("true", "1", "yes", "t", "y"):
        return "active"
    if s in ("false", "0", "no", "f", "n"):
        return "inactive"
    return str(v).strip()


sources = {
    "source_a": load("/data/source_a/users.json", "json"),
    "source_b": load("/data/source_b/users.csv", "csv"),
    "source_c": load("/data/source_c/users.parquet", "parquet"),
}

# normalize each source into records keyed by user_id -> dict of unified fields
norm = {}
for src_name, df in sources.items():
    df = df.copy()
    df.columns = [str(c).strip() for c in df.columns]
    lower = {c.lower(): c for c in df.columns}
    recs = {}
    for _, row in df.iterrows():
        rec = {}
        for canon, aliases in MAPS[src_name].items():
            val = None
            for a in aliases:
                col = lower.get(a.lower())
                if col is not None:
                    val = clean(row[col])
                    if val is not None:
                        break
            if canon == "user_id":
                if val is None:
                    continue
                if isinstance(val, bool):
                    continue
                try:
                    rec[canon] = int(float(str(val).strip()))
                except Exception:
                    try:
                        rec[canon] = int(val)
                    except Exception:
                        continue
            elif canon == "created_date":
                rec[canon] = normalize_date(val)
            elif canon == "status":
                rec[canon] = norm_status(val)
            else:
                rec[canon] = val if not isinstance(val, str) else val.strip()
        if "user_id" in rec:
            recs.setdefault(rec["user_id"], rec)
    norm[src_name] = recs

priority = ["source_a", "source_b", "source_c"]
all_ids = sorted({uid for s in norm.values() for uid in s})

rows = []
conflicts = []
for uid in all_ids:
    merged = {"user_id": uid}
    avail = {s: norm[s][uid] for s in priority if uid in norm[s]}
    for field in ["name", "email", "created_date", "status"]:
        values = {}
        for s in priority:
            if s in avail and avail[s].get(field) is not None:
                values[s] = avail[s][field]
        if not values:
            merged[field] = None
            continue
        selected = None
        for s in priority:
            if s in values:
                selected = values[s]
                break
        merged[field] = selected
        if len(values) > 1 and len({str(v) for v in values.values()}) > 1:
            conflicts.append({
                "user_id": uid,
                "field": field,
                "values": values,
                "selected": selected,
            })
    rows.append(merged)

conflicts.sort(key=lambda c: (c["user_id"], ["name", "email", "created_date", "status"].index(c["field"])))

out = pd.DataFrame(rows, columns=["user_id", "name", "email", "created_date", "status"])
out["user_id"] = out["user_id"].astype("int64")
for c in ["name", "email", "created_date", "status"]:
    out[c] = out[c].astype("object").where(out[c].notna(), None).astype("string")
out = out.sort_values("user_id").reset_index(drop=True)

table = pa.Table.from_pandas(out, preserve_index=False)
pq.write_table(table, "/app/merged_users.parquet")

report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
with open("/app/conflicts.json", "w") as f:
    json.dump(report, f, indent=2, default=str)

print(out.to_string())
print(out.dtypes)
print(json.dumps(report, indent=2, default=str))
