priority = ["source_a", "source_b", "source_c"]
all_ids = sorted({uid for s in norm.values() for uid in s})

rows = []
conflicts = []
for uid in all_ids:
    merged = {"user_id": uid}
    avail = {s: norm[s][uid] for s in priority if uid in norm[s]}
    for field in ["name", "email", "created_date", "status"]:
        values = {}
        for s in priority:
            if s in avail and avail[s].get(field) is not None:
                values[s] = avail[s][field]
        if not values:
            merged[field] = None
            continue
        selected = None
        for s in priority:
            if s in values:
                selected = values[s]
                break
        merged[field] = selected
        if len(values) > 1 and len({str(v) for v in values.values()}) > 1:
            conflicts.append({
                "user_id": uid,
                "field": field,
                "values": values,
                "selected": selected,
            })
    rows.append(merged)

conflicts.sort(key=lambda c: (c["user_id"], ["name", "email", "created_date", "status"].index(c["field"])))

out = pd.DataFrame(rows, columns=["user_id", "name", "email", "created_date", "status"])
out["user_id"] = out["user_id"].astype("int64")
for c in ["name", "email", "created_date", "status"]:
    out[c] = out[c].astype("object").where(out[c].notna(), None).astype("string")
out = out.sort_values("user_id").reset_index(drop=True)

table = pa.Table.from_pandas(out, preserve_index=False)
pq.write_table(table, "/app/merged_users.parquet")

report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
with open("/app/conflicts.json", "w") as f:
    json.dump(report, f, indent=2, default=str)

print(out.to_string())
print(out.dtypes)
print(json.dumps(report, indent=2, default=str))
